<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { IonApp, IonButton, IonCard, IonCardContent, IonContent, IonHeader, IonInput, IonItem, IonLabel, IonList, IonNote, IonTitle, IonToolbar } from '@ionic/vue'
import { createPlayer, nextPlayer, playCard, playerName, startMatch } from './game'
import { enableBluetooth, isNativeBluetooth, joinRoom, listen, message, searchRooms, send, startHost } from './bluetooth'
import { clearHistory, deleteHistory, getHistory, saveHistory } from './storage'
import type { HistoryItem, Match, Player } from './types'
type Screen = 'inicio' | 'identificacao' | 'conexao' | 'sala' | 'jogo' | 'resultado' | 'historico' | 'detalhes'
const screen = ref<Screen>('inicio'), name = ref(''), error = ref(''), notice = ref(''), busy = ref(false)
const me = ref<Player | null>(null), room = ref<Player[]>([]), match = ref<Match | null>(null), selected = ref('')
const history = ref<HistoryItem[]>([]), detail = ref<HistoryItem | null>(null)
const role = ref<'demo' | 'host' | 'client'>('demo'), foundRooms = ref<{ deviceId: string; name: string }[]>([]), pending = ref<{ id: string; name: string; deviceId: string }[]>([])
const local = computed(() => match.value?.players.find(p => p.id === me.value?.id))
const isMyTurn = computed(() => match.value?.turnPlayerId === me.value?.id)
const destination = computed(() => match.value && me.value ? nextPlayer(match.value, me.value.id).name : '')
function go(to: Screen) { error.value = ''; notice.value = ''; screen.value = to }
function back() { const previous: Partial<Record<Screen, Screen>> = { identificacao: 'inicio', conexao: 'identificacao', sala: 'conexao', jogo: 'sala', resultado: 'inicio', historico: 'inicio', detalhes: 'historico' }; const target = previous[screen.value]; if (target) go(target) }
async function createBluetoothRoom() { if (!me.value) return; busy.value = true; try { await startHost(); role.value = 'host'; me.value.isHost = true; room.value = [me.value]; notice.value = 'Sala anunciada. Aguarde pedidos de entrada.'; go('sala') } catch (e) { error.value = e instanceof Error ? e.message : 'Falha ao criar sala Bluetooth.' } finally { busy.value = false } }
async function findBluetoothRooms() { busy.value = true; foundRooms.value = []; try { await searchRooms(device => { if (!foundRooms.value.some(x => x.deviceId === device.deviceId)) foundRooms.value.push(device) }); notice.value = 'Procurando salas Bluetooth próximas...'; } catch (e) { error.value = e instanceof Error ? e.message : 'Falha ao procurar salas.' } finally { busy.value = false } }
async function enterBluetoothRoom(deviceId: string) { role.value = 'client'; busy.value = true; try { await joinRoom(deviceId); notice.value = 'Conectando ao anfitrião...'; } catch (e) { error.value = e instanceof Error ? e.message : 'Falha ao conectar.' } finally { busy.value = false } }
async function approve(player: { id: string; name: string; deviceId: string }) { if (!me.value || room.value.length >= 6) return; room.value.push({ ...createPlayer(player.name), id: player.id, deviceId: player.deviceId }); pending.value = pending.value.filter(x => x.id !== player.id); await send(message('JOGADOR_ENTROU', 'sala', me.value.id, { players: room.value.map(p => ({ id: p.id, name: p.name, isHost: p.isHost, connected: p.connected, burro: p.burro })) })); }
function reject(playerId: string) { pending.value = pending.value.filter(x => x.id !== playerId) }
function identify() { if (name.value.trim().length < 2) return error.value = 'Informe um nome com ao menos 2 caracteres.'; me.value = createPlayer(name.value, true); room.value = [me.value]; go('conexao') }
async function connect() { busy.value = true; try { await enableBluetooth(); notice.value = 'Bluetooth pronto. Em dispositivos reais, procure o anfitrião nas proximidades.'; go('sala') } catch { error.value = 'Não foi possível ativar o Bluetooth. Verifique a permissão e se ele está ligado.' } finally { busy.value = false } }
function addDemoPlayer() { room.value.push(createPlayer(`Jogador ${room.value.length + 1}`)) }
function removePlayer(id: string) { room.value = room.value.filter(p => p.id !== id) }
function begin() { try { match.value = startMatch(room.value); selected.value = ''; go('jogo') } catch (e) { error.value = e instanceof Error ? e.message : 'Erro ao iniciar.' } }
async function confirmCard() { if (!match.value || !me.value || !selected.value) return error.value = 'Selecione uma carta.'; try { match.value = playCard(match.value, me.value.id, selected.value); selected.value = ''; if (match.value.status === 'finalizada') await finish() } catch (e) { error.value = e instanceof Error ? e.message : 'Jogada inválida.' } }
async function simulateOpponent() { if (!match.value || isMyTurn.value) return; const opponent = match.value.players.find(p => p.id === match.value?.turnPlayerId); if (!opponent?.hand[0]) return; match.value = playCard(match.value, opponent.id, opponent.hand[0].id); if (match.value.status === 'finalizada') await finish() }
async function finish() { if (!match.value || !me.value) return; const item: HistoryItem = { ...match.value, localResult: match.value.winnerId === me.value.id ? 'vitória' : match.value.penalizedId === me.value.id ? 'penalizado' : 'participou' }; await saveHistory(item); detail.value = item; go('resultado') }
async function openHistory() { history.value = await getHistory(); go('historico') }
async function erase(id: string) { if (confirm('Excluir esta partida do histórico?')) { await deleteHistory(id); history.value = await getHistory() } }
async function eraseAll() { if (confirm('Limpar todo o histórico? Esta ação não pode ser desfeita.')) { await clearHistory(); history.value = [] } }
function newGame() { match.value = null; room.value = me.value ? [{ ...me.value, hand: [] }] : []; go('conexao') }
const symbol: Record<string, string> = { copas: '♥', ouros: '♦', paus: '♣', espadas: '♠' }
void connect
onMounted(() => { listen(async (value, deviceId) => { if (!me.value) return; if (value.type === 'SOLICITACAO_ENTRADA' && role.value === 'host') { const candidate = value.payload as { name?: string; playerId?: string }; if (candidate.name && candidate.playerId && !pending.value.some(p => p.id === candidate.playerId)) pending.value.push({ id: candidate.playerId, name: candidate.name, deviceId }); } if (value.type === 'JOGADOR_ENTROU' && role.value === 'client') { const players = value.payload.players as Player[] | undefined; if (players) { room.value = players.map(p => ({ ...p, hand: [] })); go('sala') } } }, async (state, deviceId) => { if (state === 'CONECTADO' && role.value === 'client' && me.value) await send(message('SOLICITACAO_ENTRADA', 'sala', me.value.id, { name: me.value.name, playerId: me.value.id })); if (state === 'DESCONECTADO') notice.value = `Dispositivo ${deviceId} desconectou.` }, value => error.value = value) })
</script>

<template><ion-app><ion-header><ion-toolbar color="primary"><ion-button v-if="screen !== 'inicio'" slot="start" fill="clear" color="light" aria-label="Voltar" @click="back">‹</ion-button><ion-title>Jogo do Jegue</ion-title></ion-toolbar></ion-header><ion-content class="ion-padding"><main>
  <p v-if="error" class="error">{{ error }}</p><p v-if="notice" class="notice">{{ notice }}</p>
  <section v-if="screen === 'inicio'" class="center hero-screen"><div class="donkey">♞</div><span class="eyebrow">BLUETOOTH • MULTIPLAYER</span><h1>Jogo do Jegue</h1><p>Forme quatro cartas do mesmo valor antes dos outros jogadores.</p><ion-button expand="block" @click="go('identificacao')">Jogar agora</ion-button><ion-button fill="outline" expand="block" @click="openHistory">Histórico</ion-button></section>
  <section v-else-if="screen === 'identificacao'"><h2>Quem vai jogar?</h2><ion-item><ion-input v-model="name" label="Seu nome" label-placement="stacked" placeholder="Ex.: Gabriel"></ion-input></ion-item><ion-button expand="block" @click="identify">Continuar</ion-button></section>
  <section v-else-if="screen === 'conexao'"><h2>Conexão Bluetooth</h2><p v-if="isNativeBluetooth()">Crie uma sala neste celular ou procure um anfitrião próximo.</p><p v-else>Bluetooth real funciona no APK Android. No navegador, use a demonstração.</p><ion-button expand="block" :disabled="busy" @click="createBluetoothRoom">Criar sala Bluetooth</ion-button><ion-button expand="block" fill="outline" :disabled="busy" @click="findBluetoothRooms">Procurar salas Bluetooth</ion-button><ion-list v-if="foundRooms.length"><ion-item v-for="device in foundRooms" :key="device.deviceId"><ion-label>{{ device.name }}</ion-label><ion-button @click="enterBluetoothRoom(device.deviceId)">Entrar</ion-button></ion-item></ion-list><ion-button fill="clear" @click="room = me ? [me] : []; role = 'demo'; go('sala')">Modo demonstração</ion-button></section>
  <section v-else-if="screen === 'sala'"><h2>Sala de espera</h2><p><b>Anfitrião:</b> {{ room.find(p => p.isHost)?.name ?? 'aguardando' }} · {{ room.length }}/6 · {{ role === 'demo' ? 'demonstração' : 'Bluetooth conectado' }}</p><ion-list><ion-item v-for="p in room" :key="p.id"><ion-label>{{ p.name }} <ion-note v-if="p.isHost">(anfitrião)</ion-note></ion-label><ion-button v-if="role === 'host' && p.id !== me?.id" fill="clear" color="danger" @click="removePlayer(p.id)">Remover</ion-button></ion-item><ion-item v-for="p in pending" :key="p.id"><ion-label>Pedido: {{ p.name }}</ion-label><ion-button color="success" @click="approve(p)">Aceitar</ion-button><ion-button color="danger" fill="clear" @click="reject(p.id)">Recusar</ion-button></ion-item></ion-list><ion-button v-if="role === 'demo'" fill="outline" :disabled="room.length >= 6" @click="addDemoPlayer">Aceitar jogador (demo)</ion-button><ion-button v-if="role !== 'client'" expand="block" :disabled="room.length < 2" @click="begin">Iniciar partida</ion-button><p v-else>Aguarde o anfitrião aceitar sua entrada e iniciar a partida.</p></section>
  <section v-else-if="screen === 'jogo' && match && local"><div class="status"><span>Rodada {{ match.rounds + 1 }}</span><b :class="{ turn: isMyTurn }">{{ isMyTurn ? 'É sua vez!' : `Vez de ${playerName(match, match.turnPlayerId)}` }}</b></div><p>Você envia para <b>{{ destination }}</b>. Cada carta só aparece na sua mão.</p><h2>Sua mão ({{ local.hand.length }})</h2><div class="cards"><button v-for="card in local.hand" :key="card.id" class="card" :class="[{ selected: selected === card.id }, card.suit]" :disabled="!isMyTurn" @click="selected = card.id"><strong>{{ card.value }}</strong><span>{{ symbol[card.suit] }}</span></button></div><ion-button expand="block" :disabled="!isMyTurn || !selected" @click="confirmCard">Confirmar envio</ion-button><ion-button v-if="!isMyTurn" fill="outline" expand="block" @click="simulateOpponent">Simular turno do adversário (demo)</ion-button><p class="small">Jogadas fora do turno são bloqueadas pelo motor do jogo e validadas antes da sincronização.</p></section>
  <section v-else-if="screen === 'resultado' && detail" class="center"><h2>Partida finalizada</h2><ion-card><ion-card-content><p>Vencedor: <b>{{ playerName(detail, detail.winnerId) }}</b></p><p>Penalizado: <b>{{ playerName(detail, detail.penalizedId) }}</b></p><p>{{ detail.endReason }} · {{ detail.rounds }} rodadas</p></ion-card-content></ion-card><ion-button expand="block" @click="newGame">Nova partida</ion-button><ion-button fill="outline" expand="block" @click="openHistory">Ver histórico</ion-button></section>
  <section v-else-if="screen === 'historico'"><h2>Histórico</h2><p v-if="!history.length">Nenhuma partida registrada ainda.</p><ion-list><ion-item v-for="item in history" :key="item.id" button @click="detail = item; go('detalhes')"><ion-label><b>{{ new Date(item.startedAt).toLocaleString('pt-BR') }}</b><p>{{ item.players.length }} jogadores · {{ item.status }} · {{ item.localResult }}</p></ion-label><ion-button fill="clear" color="danger" @click.stop="erase(item.id)">Excluir</ion-button></ion-item></ion-list><ion-button v-if="history.length" color="danger" fill="outline" @click="eraseAll">Limpar histórico</ion-button><ion-button fill="clear" @click="go('inicio')">Voltar</ion-button></section>
  <section v-else-if="screen === 'detalhes' && detail"><h2>Detalhes da partida</h2><ion-card><ion-card-content><p>Início: {{ new Date(detail.startedAt).toLocaleString('pt-BR') }}</p><p>Término: {{ detail.endedAt ? new Date(detail.endedAt).toLocaleString('pt-BR') : '—' }}</p><p>Ordem: {{ detail.players.map(p => p.name).join(' → ') }}</p><p>Vencedor: {{ playerName(detail, detail.winnerId) }}</p><p>Penalizado: {{ playerName(detail, detail.penalizedId) }}</p><p>Rodadas: {{ detail.rounds }} · Motivo: {{ detail.endReason ?? detail.status }}</p></ion-card-content></ion-card><ion-button @click="openHistory">Voltar ao histórico</ion-button></section>
</main></ion-content></ion-app></template>
